/** Starts the app on an ephemeral port for one test file; each file gets a fresh store. */

import { createServer, type Server } from "node:http";
import type { AddressInfo } from "node:net";

import { createApp } from "../src/app.ts";

export interface Running {
  readonly url: string;
  close(): Promise<void>;
}

export async function start(): Promise<Running> {
  const server: Server = createServer(createApp());
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const { port } = server.address() as AddressInfo;
  return {
    url: `http://127.0.0.1:${port}`,
    close: () => new Promise<void>((resolve) => server.close(() => resolve())),
  };
}

export async function json(response: Response): Promise<Record<string, unknown>> {
  return (await response.json()) as Record<string, unknown>;
}

export function post(url: string, body: unknown): Promise<Response> {
  return fetch(url, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
}

export function patch(url: string, body: unknown): Promise<Response> {
  return fetch(url, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
}

import assert from "node:assert/strict";
import { after, before, it } from "node:test";

import { json, type Running, start } from "./server.ts";

let app: Running;
before(async () => {
  app = await start();
});
after(() => app.close());

it("reports healthy", async () => {
  const response = await fetch(`${app.url}/healthz`);
  assert.equal(response.status, 200);
  assert.deepEqual(await json(response), { status: "ok" });
});

import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";

import { json, patch, post, type Running, start } from "./server.ts";

const PAYLOAD = { name: "example name", price: 9.5, stock: 3, active: true };

describe("/products", () => {
  let app: Running;
  before(async () => {
    app = await start();
  });
  after(() => app.close());

  it("creates and reads one", async () => {
    const response = await post(`${app.url}/products`, PAYLOAD);
    assert.equal(response.status, 201);
    const created = await json(response);
    assert.equal(created.name, PAYLOAD.name);
    assert.equal(created.price, PAYLOAD.price);
    assert.equal(created.stock, PAYLOAD.stock);
    assert.equal(created.active, PAYLOAD.active);
    const fetched = await fetch(`${app.url}/products/${created.id}`);
    assert.equal(fetched.status, 200);
    assert.equal((await json(fetched)).id, created.id);
  });

  it("lists with limit and offset", async () => {
    for (let i = 0; i < 3; i++) {
      assert.equal((await post(`${app.url}/products`, PAYLOAD)).status, 201);
    }
    const page = await fetch(`${app.url}/products?limit=2&offset=1`);
    assert.equal(page.status, 200);
    assert.equal(((await page.json()) as unknown[]).length, 2);
    assert.equal((await fetch(`${app.url}/products?limit=0`)).status, 422);
  });

  it("updates one", async () => {
    const created = await json(await post(`${app.url}/products`, PAYLOAD));
    const response = await patch(`${app.url}/products/${created.id}`, { name: "updated name" });
    assert.equal(response.status, 200);
    assert.equal((await json(response)).name, "updated name");
  });

  it("deletes one", async () => {
    const created = await json(await post(`${app.url}/products`, PAYLOAD));
    const deleted = await fetch(`${app.url}/products/${created.id}`, { method: "DELETE" });
    assert.equal(deleted.status, 204);
    assert.equal((await fetch(`${app.url}/products/${created.id}`)).status, 404);
  });

  it("answers 404 for an unknown id", async () => {
    assert.equal((await fetch(`${app.url}/products/999999`)).status, 404);
    assert.equal((await fetch(`${app.url}/products/not-a-number`)).status, 404);
  });

  it("rejects invalid input with 422", async () => {
    assert.equal((await post(`${app.url}/products`, { unknown_field: 1 })).status, 422);
    assert.equal((await post(`${app.url}/products`, {})).status, 422);
  });
});

